import{_ as r,o as e,b as d,q as a}from"./chunks/framework.Tf23FRXt.js";const c=JSON.parse('{"title":"国际服","description":"","frontmatter":{},"headers":[{"level":2,"title":"国服和其他服的区别","slug":"国服和其他服的区别","link":"#国服和其他服的区别","children":[]},{"level":2,"title":"其他服入坑","slug":"其他服入坑","link":"#其他服入坑","children":[]}],"relativePath":"basic/international.htm.md","filePath":"basic/international.md","lastUpdated":1791098838000}'),n={name:"basic/international.htm.md"};function i(l,t,s,o,p,h){return e(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="国际服" tabindex="-1">国际服</h1><p>《最终幻想 14》在运营上大致可分为<strong>国服</strong>、<strong>国际服</strong>、<strong>韩服</strong>和<strong>繁中服</strong>四方。这四者由四个不同的公司运营：国服由盛大（盛趣）运营，国际服由游戏开发商 SquareEnix（SE） 自己运营，韩服由被盛大收购的韩国老牌游戏运营商 Actoz Soft 运营，繁中服由宇峻奧汀代理运营。</p><h2 id="国服和其他服的区别" tabindex="-1">国服和其他服的区别</h2><p>国服和其他服的游戏内容是完全一致的，入坑后您均可参照本站的其他相关信息进行游戏。</p><div class="md-table"><table class="ui compact grey striped unstackable table"><thead><tr><th></th><th>国服</th><th>其他服</th></tr></thead><tbody><tr><td>更新时间</td><td>标准</td><td>国际服同步；韩服滞后 1 个小版本，预计即将同步；繁中服滞后多个小版本，预计将来同步。</td></tr><tr><td>节日活动</td><td>标准</td><td>同步</td></tr><tr><td>文本语言</td><td>中文</td><td>国际服：日、英、德、法；韩服：韩文；繁中服：繁体中文</td></tr><tr><td>配音语言</td><td>中、日</td><td>国际服：日、英、德、法；韩服：韩语；繁中服：日语</td></tr><tr><td>区服信息</td><td>分 4 个大区，共 27 个服务器</td><td>国际服：按北美、欧洲、日本、大洋洲分 4 个 DC，共 10 个大区，81 个服务器</td></tr><tr><td>玩家群体</td><td>以国内玩家为主，有部分留学生，及其他华语地区玩家。</td><td>各 DC 以地域各自分布地区，但实际各地人群都有，也有部分非运营地区玩家（中韩新马等）。</td></tr><tr><td>购买方式</td><td>点卡 / 月卡，无需 CDKey</td><td>CDKey + 月卡，没有点卡</td></tr><tr><td>额外雇员</td><td>买断</td><td>月租</td></tr><tr><td>运行平台</td><td>仅 Windows (盛趣，WeGame)</td><td>Windows (Steam), MacOS, PS4, PS5 （账号数据互通，游戏需每平台单独购买）</td></tr></tbody></table></div><h2 id="其他服入坑" tabindex="-1">其他服入坑</h2><p>如果你访问其他服速度更快，并且熟悉理解对应语言，可以尝试体验其他服的玩法。虽然国际服玩家群体混杂，但仍旧会根据本服内主体玩家的地域不同而形成各自的风气，<strong>请各位记得入乡随俗</strong>。</p><p>注册和激活国际服需要有稳定的访问外网的工具，另外还需要可以支付外币的信用卡或借记卡。</p><p>日本不支持海外发行的信用卡，可以使用 WebMoney、BitCash 或 Amazon Pay、Pay Pal 等方式支付。</p><p><strong>切勿使用线上代充、代购，会有账号被封停的风险！</strong></p><ul><li><a href="https://bbs.nga.cn/read.php?tid=30267714" target="_blank" rel="noreferrer">信用卡与外币注册支付指南</a></li><li><a href="https://bbs.nga.cn/read.php?tid=30313559" target="_blank" rel="noreferrer">外币借记卡申请 / 使用指南 by jawwe</a></li><li><a href="https://bbs.nga.cn/read.php?tid=15259943" target="_blank" rel="noreferrer">国际服入坑指北 by Cataria 卡塔</a></li><li><a href="https://bbs.nga.cn/read.php?tid=30280757" target="_blank" rel="noreferrer">国际服 Steam 版购买指南 by aqjcy520</a></li><li><a href="https://www.bilibili.com/read/cv11570492" target="_blank" rel="noreferrer">国际服获取注册激活游玩从入门到精通 by 西木野真姫</a></li></ul>',11)])])}const _=r(n,[["render",i]]);export{c as __pageData,_ as default};
